#Region @DOC
#### Description:
#Copies a file from the file storage of a source database to the file storage of a target database over the REST API (`/Contents('Files')`).
#
#### How to Use:
#
#- `pFile`: REQUIRED: the file path within the source file storage, with `/` between folders, e.g. `exports/sales.csv`.
#- `pTargetPath`: OPTIONAL: the target file path.
#  - If blank, the same path as `pFile` is used.
#  - If it ends with `/`, it is treated as a folder and the file keeps its name.
#  - If it starts with `/`, it is relative to the root of the file storage. Otherwise it is relative to the folder of `pFile`.
#  - Missing target folders are created.
#- `pDeleteSourceFile`: 1 = delete the source file after a successful copy.
#- `pMultiPartUpload`: 1 = transfer the file in chunks of `pChunkSize` bytes, for large files.
#- `pSourceConnectionName` / `pTargetConnectionName`: connection names configured in `}bedrock.session.start`, or connection-details JSON objects returned by it. A blank `pTargetConnectionName` means the same connection as the source. If they are the same, one session is used for both.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pSourceConnectionName":  null,
  "pTargetConnectionName":  null,
  "pFile":                "",
  "pLogOutput":           0,
  "pStrictErrorHandling": 0,
  "pTargetPath": "",
  "pDeleteSourceFile": 0,
  "pChunkSize": 104857600,
  "pMultiPartUpload": 0
}';

pPassedParameters = '{
  "pSourceConnectionName":  '|StringToJson  ( pSourceConnectionName  )|',
  "pTargetConnectionName":  '|StringToJson  ( pTargetConnectionName  )|',
  "pFile":                '|StringToJson( pFile                )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|',
  "pTargetPath": '|StringToJson( pTargetPath )|',
  "pDeleteSourceFile": '|NumberToString( pDeleteSourceFile )|',
  "pChunkSize": '|NumberToString( pChunkSize )|',
  "pMultiPartUpload": '|NumberToString( pMultiPartUpload )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
pTargetPath = JsonToString( pJson, '/pTargetPath' );
pDeleteSourceFile = StringToNumber( JsonToString( pJson, '/pDeleteSourceFile' ) );
pChunkSize = StringToNumber( JsonToString( pJson, '/pChunkSize' ) );
pMultiPartUpload = StringToNumber( JsonToString( pJson, '/pMultiPartUpload' ) );
# String Parameters
IF( JsonType( JsonGet( pJson, '/pSourceConnectionName' ) ) @= 'string' );
  pSourceConnectionName = JsonToString( pJson, '/pSourceConnectionName' );
ELSE;
  pSourceConnectionName = JsonGet( pJson, '/pSourceConnectionName' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pTargetConnectionName' ) ) @= 'string' );
  pTargetConnectionName = JsonToString( pJson, '/pTargetConnectionName' );
ELSE;
  pTargetConnectionName = JsonGet( pJson, '/pTargetConnectionName' );
ENDIF;
pFile                =                 JsonToString( pJson, '/pFile'                );
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceConnectionName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pSourceConnectionName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceConnectionName;
ENDIF;
sSourceURL = JsonToString( sSourceConnectionDetails, '/sURL' );

### Authentication headers for requests to this connection
sSrcAuthHeaders = '[]';
IF( JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sSourceConnectionDetails, '/sSID' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sSourceConnectionDetails, '/sSID' ) ) );
ENDIF;


### A blank target means the same connection as the source
IF( pTargetConnectionName @= '' );
  pTargetConnectionName = pSourceConnectionName;
ENDIF;

IF( pSourceConnectionName @= pTargetConnectionName );
  sTargetConnectionDetails = sSourceConnectionDetails;
ELSE;
  sTargetDatabaseParameterType = JsonType( pTargetConnectionName );
  IF( sTargetDatabaseParameterType @<> 'object' );
    ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pTargetConnectionName, 'pJson', pJson ); sTargetConnectionDetails = sBedrockReturnValue;
  ELSE;
    sTargetConnectionDetails = pTargetConnectionName;
  ENDIF;
ENDIF;
sTargetURL = JsonToString( sTargetConnectionDetails, '/sURL' );

### Authentication headers for requests to this connection
sTgtAuthHeaders = '[]';
IF( JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sTargetConnectionDetails, '/sSID' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sTargetConnectionDetails, '/sSID' ) ) );
ENDIF;


IF( pTargetPath @= '' );
  pTargetPath = pFile;
ENDIF;

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Get File from Source

cTempFile = '.tmp/'|cTemp;

# Convert pFile into Contents Folders URL
ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pFile, 'pDelimiter','/', 'pJson', pJson ); sFileSplit = sBedrockReturnValue;

sSourceFilePath = '["Files"]';
sSourceFileURL = '/Contents(''Files'')';

nSize = JsonSize( sFileSplit );
i = 0;
WHILE( i < nSize );
  sFileName = JsonToString( sFileSplit, i );
  sSourceFileURL = sSourceFileURL | '/Contents('''|URLEncode( sFileName )|''')';
  sSourceFilePath  = JsonAdd( sSourceFilePath, '', StringToJson( sFileName ) );
  i = i + 1;
END;

#EndRegion - Get File from Source
#################################################################################################

#################################################################################################
#Region - Upload File to Target

ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pTargetPath, 'pDelimiter','/', 'pJson', pJson ); sFileSplit = sBedrockReturnValue;

IF( SUBST( pTargetPath, LONG( pTargetPath ), 1 ) @= '/' );
  sFileSplit = JsonAdd( sFileSplit, '', StringToJson( sFileName ) );
ENDIF;

# Relative vs. Absolute Path
IF( SUBST( pTargetPath, 1, 1 ) @= '/' );
  sTargetFilePath = '["Files"]';
ELSE;
  sTargetFilePath = JsonRemove( sSourceFilePath, JsonSize( sSourceFilePath ) - 1 );
ENDIF;

# Combine sTargetFileURL and sFileSplit
i = 0;
WHILE( i < JsonSize( sFileSplit ) );
  sTargetFilePath = JsonAdd( sTargetFilePath, '', JsonGet( sFileSplit, i ) );
  i = i + 1;
END;

# Create target folder tree
sTargetFileURL = '/Contents(''Files'')';
i = 1;
WHILE( i < JsonSize( sTargetFilePath ) - 1 );
  sTargetName = JsonToString( sTargetFilePath, i );
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | sTargetFileURL | '/Contents',
    'pHeaders', sTgtAuthHeaders,
    'pBody', '{"@odata.type": "#ibm.tm1.api.v1.Folder", "Name": '|StringToJson( sTargetName )|'}',
    'pJson', pJson 
  );
  
  sTargetFileURL = sTargetFileURL | '/Contents('''|URLEncode( sTargetName )|''')';
  i = i + 1;
END;
sTargetName = JsonGet( sTargetFilePath, JsonSize( sTargetFilePath ) - 1 );

# Create target file
ExecuteProcess('}bedrock.process.execute_http_request',
  'pMethod', 'POST',
  'pURL', sTargetURL | sTargetFileURL | '/Contents',
  'pHeaders', sTgtAuthHeaders,
  'pBody', '{"@odata.type": "#ibm.tm1.api.v1.Document", "ID": '|sTargetName|', "Name": '|sTargetName|'}',
  'pJson', pJson
);
sTargetFileURL = sTargetFileURL | '/Contents('''|URLEncode( JsonToString( sTargetName ) )|''')';

IF( pMultiPartUpload = 0 );
  # Get file content
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'GET',
    'pURL', sSourceURL | sSourceFileURL | '/Content',
    'pHeaders', JsonAdd( sSrcAuthHeaders, '', '"Accept-Encoding: gzip, deflate"' ),
    'pResponseFile', cTempFile|'.blb',
    'pJson', pJson );
  
  # Populate file
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'PUT',
    'pURL', sTargetURL | sTargetFileURL | '/Content',
    'pHeaders', sTgtAuthHeaders,
    'pBody', '@'|cTempFile|'.blb',
    'pJson', pJson 
  );
  
ELSE;
  # Get source file size
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod', 'GET',
    'pURL', sSourceURL | sSourceFileURL | '?$select=Size',
    'pHeaders', sSrcAuthHeaders,
    'pJson', pJson );
  nTotalBytes = StringToNumber( JsonGet( sBedrockReturnValue, '/body/Size' ) );
  nBytesProcessed = 0;
  i = 0;
  
  # Chunk the source file size
  WHILE( nBytesProcessed < nTotalBytes );
    ExecuteProcess('}bedrock.process.execute_http_request',
      'pMethod', 'GET',
      'pURL', sSourceURL | sSourceFileURL | '/Content',
      'pHeaders', JsonAdd( JsonAdd( sSrcAuthHeaders, '', '"Accept-Encoding: gzip, deflate"' ), '', '"Range: bytes=''|NumberToString( i * pChunkSize )|''-''|NumberToString( ( ( i + 1 ) * pChunkSize ) - 1 )|''"' ),
      'pResponseFile', cTempFile|'_chunk_'|NumberToString(i)|'.blb',
      'pJson', pJson );
    nBytesProcessed = nBytesProcessed + pChunkSize;
    i = i + 1;
  END;
  
  # Start multi-part upload
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | sTargetFileURL | '/Content/mpu.CreateMultipartUpload',
    'pHeaders', sTgtAuthHeaders,
    'pBody', '{}',
    'pJson', pJson
  );
  sUploadID = JsonToString( sBedrockReturnValue, '/body/UploadID' );
  
  sParts = '[]';
  q = 0;
  WHILE( q < i );
    # Upload chunk
    ExecuteProcess('}bedrock.process.execute_http_request',
      'pMethod', 'POST',
      'pURL', sTargetURL | sTargetFileURL | '/Content/!uploads('''|sUploadID|''')/Parts',
      'pHeaders', sTgtAuthHeaders,
      'pBody', '@'|cTempFile|'_chunk_'|NumberToString(q)|'.blb',
      'pJson', pJson 
    );
    sParts = JsonAdd( sParts, '', '{"PartNumber": '|JsonGet( sBedrockReturnValue, '/body/PartNumber' )|', "ETag": '|JsonGet( sBedrockReturnValue, '/body/@odata.etag' )|'}' );
    q = q + 1;
  END;
  
  # Finish multi-part upload
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | sTargetFileURL | '/Content/!uploads('''|sUploadID|''')/mpu.Complete',
    'pHeaders', sTgtAuthHeaders,
    'pBody', '{"Parts": '|sParts|'}',
    'pJson', pJson 
  );
  
  # Delete temporary chunk files
  q = 0;
  WHILE( q < i );
    ASCIIDelete( cTempFile|'_chunk_'|NumberToString(q)|'.blb' );
    q = q + 1;
  END;
    
ENDIF;

# Delete the source file only if the new file was created successfully
IF( pDeleteSourceFile = 1 & StringToNumber( JsonGet( sBedrockReturnValue, '/status_code' ) ) < 400 );
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'DELETE',
    'pURL', sSourceURL | sSourceFileURL,
    'pHeaders', sSrcAuthHeaders,
    'pJson', pJson
  );
ENDIF;

#EndRegion - Upload File to Target
#################################################################################################

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

#################################################################################################
#Region - Cleanup

IF( FileExists( cTempFile|'.blb' ) = 1 );
  ASCIIDelete( cTempFile|'.blb' );
ENDIF;

IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sSourceURL | '/ActiveSession/tm1.Close',
    'pHeaders', sSrcAuthHeaders,
    'pJson', pJson 
  );
ENDIF;

IF( sTargetDatabaseParameterType @<> 'object' & pSourceConnectionName @<> pTargetConnectionName);
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | '/ActiveSession/tm1.Close',
    'pHeaders', sTgtAuthHeaders,
    'pJson', pJson 
  );
ENDIF;

#EndRegion - Cleanup
#################################################################################################
